def largest_prime_factor(n: int):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    max_prime = -1
    while n % 2 == 0:
        max_prime = 2
        n //= 2

    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            if is_prime(i):
                max_prime = i
            n //= i

    if n > 2 and is_prime(n):
        max_prime = n

    return max_prime

