def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def dfs(x, y, path):
        if len(path) == k:
            return path
        result = []
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                new_path = dfs(nx, ny, path + [grid[nx][ny]])
                if new_path:
                    result.append(new_path)
        return min(result) if result else None

    paths = []
    for i in range(N):
        for j in range(N):
            initial_path = dfs(i, j, [grid[i][j]])
            if initial_path:
                paths.append(initial_path)

    return min(paths)

